\label{prop:absorption}
If $\mathcal{C}_{n+1}=\mathcal{C}_n$, then $\mathcal{C}_j=\mathcal{C}_n$ for all $j\ge n$.
Every $G^{(m)}$ with $m\ge2n+1$ is then an equivalence.

\label{lem:square-zero-annihilator}
Set $J_\mathcal{T}=\operatorname{Ann}_\Lambda\mathcal{T}\cap\operatorname{Ann}_\Lambda\mathcal{F}$.
Then the following hold.
\begin{enumerate}
\item[(1)] $J_\mathcal{T}^2=0$, $I_n\subseteq J_\mathcal{T}$ for all $n$;
\item[(2)]
		$\operatorname{Ann}_{\Lambda_n}\mathcal{T}_n\cap\operatorname{Ann}_{\Lambda_n}\mathcal{F}_n=J_\mathcal{T}/I_n.$
\end{enumerate}

\label{thm:hrs-ideal-recursion}
The HRS ideal filtration is determined recursively by
\begin{equation}\label{eq:hrs-ideal-recursion}
I_{n+1}/I_n=I_{\Lambda_n}(\mathcal{T}_n),\qquad
\Lambda_{n+1}=\Lambda_n/I_{\Lambda_n}(\mathcal{T}_n).
\end{equation}
All $I_n$ and $\mathcal{C}_n$ are independent of the chosen realization
functors.

\label{cor:first-hrs-ideal-stopping}\label{thm:refined-height}
The following conditions are equivalent for an integer $n\geq 0$:
\begin{enumerate}
	\item[(1)]$I_{n+1}=I_n$;
		\item[(2)]$I_{\Lambda_n}(\mathcal{T}_n)=0$;
			\item[(3)]$G^{(2n+1)}$ is an equivalence.
\end{enumerate}
If $I_{n+1}=I_n$, then $I_n=I_m$ for any $m>n$.

\label{prop:hereditary-arbitrary-pair}
If $\Lambda$ is hereditary, then every torsion pair $(\mathcal{T},\mathcal{F})$ in
$\operatorname{mod}\Lambda$ satisfies $h_\Lambda(\mathcal{T})\le1$.

\label{cor:silting-faithfulness-criterion}
If $H^0(\mathbf{P})\oplus H^{-1}(\nu\mathbf{P})$ is faithful over $\Lambda$,
then $\mathbf{P}$ is tilting and $\mathfrak b_\Lambda(\mathbf{P})=0$.

\label{thm:hrs-base-change}
For every ideal $J$ of $\Lambda$, the complex
$\mathbf{P}\otimes_\Lambda\Lambda/J$ is two-term silting.
Put $\Lambda_1=\Lambda/\mathfrak b_\Lambda(\mathbf{P})$, and let
$\mathbf{P}^+$ be the Buan--Zhou successor of $\mathbf{Q}$. Then
for $\overline\mathbf{P}=\mathbf{P}\otimes_\Lambda\Lambda_1$ one has
\begin{equation}\label{eq:hrs-base-change-add}
 \operatorname{add}\overline\mathbf{P}=\operatorname{add}\mathbf{P}^+
 \quad\text{in }\mathrm K^{\mathrm b}(\operatorname{proj}\Lambda_1).
\end{equation}

\label{cor:iterated-hrs-base-change}
At every even stage of HRS tilting,
\begin{equation}\label{eq:direct-hrs-ideal-recursion}
 \operatorname{add}\mathbf{P}_i=\operatorname{add}(\mathbf{P}\otimes_\Lambda\Lambda_i),\qquad
 I_{i+1}/I_i=
 \mathfrak b_{\Lambda_i}(\mathbf{P}\otimes_\Lambda\Lambda_i).
\end{equation}

\label{prop:exact-parity-stabilization}
The heights satisfy $h_{\mathrm{odd}}\le h_{\mathrm{ev}}
\le h_{\mathrm{odd}}+1$. The least $s\ge1$ such that all
$G^{(m)}$, $m\ge s$, are equivalences is
\begin{equation}\label{eq:exact-parity-stabilization}
 \sigma_\Lambda(\mathcal{T}(\mathbf{P}))
 =\max\{2h_{\mathrm{ev}},2h_{\mathrm{odd}}+1\}
 =h_{\mathrm{ev}}+h_{\mathrm{odd}}+1.
\end{equation}

\label{lem:matrix-hrs-ideal}The first HRS ideal is given by
\begin{equation}\label{eq:matrix-hrs-ideal-equality}
 I_\Lambda(\mathcal{T}(\mathbf{P}))=\mathfrak b_\Lambda(\mathbf{P})
 =\langle a_{ji}\mid L=(a_{ji})\in\ker\Theta_{\mathbf d}\rangle,
\end{equation}
where the brackets denote the two-sided ideal generated by the entries.

\label{lem:hom-id}
	For every two-term complex $\mathbf{P}$ of finitely generated projectives,
	there is a natural isomorphism
	\begin{equation}\label{eq:kernel-negative-hom}
		\operatorname{Hom}_{\mathrm K^{\mathrm b}(\operatorname{proj}\Lambda)}(\mathbf{P},\mathbf{P}[-1])
		\simeq \operatorname{Hom}_\Lambda(H^0(\mathbf{P}),H^{-1}(\mathbf{P})).
	\end{equation}

\label{lem:kernel-first-identities}
	For $I=I_1$ one has
	\[
	I\in\mathcal{T},\quad  d(P^{-1}I)= P^0I\text{ and }
	t(H^{-1}(\mathbf{P}))\subseteq H^{-1}(\mathbf{P})\cap P^{-1}I.
	\]

\label{thm:main-kernel-filtration}
	Keep the notation above and set $R_n=H^{-1}(\mathbf{P})\cap P^{-1}I_n$.
	We have:
	\begin{enumerate}[label=(\arabic*),leftmargin=2.2em]
		\item $H^0(\mathbf{P}_n)\simeq H^{0}(\mathbf{P})$;
		\item $H^{-1}(\mathbf{P}_n)\simeq H^{-1}(\mathbf{P})/R_n$;
		\item $\operatorname{Hom}_{\mathrm K^{\mathrm b}(\operatorname{proj}\Lambda_n)}(\mathbf{P}_n,\mathbf{P}_n[-1])
		\simeq\operatorname{Hom}_\Lambda(H^{0}(\mathbf{P}),H^{-1}(\mathbf{P})/R_n)$;
		\item The two-term silting complex $\mathbf{P}_n$ is tilting if and only if
		$H^{-1}(\mathbf{P})/R_n\in\mathcal{F}$.
	\end{enumerate}
	In particular,
	\begin{equation}\label{eq:kernel-height}
		h_\Lambda(\mathbf{P})=\min\{n\ge0:\operatorname{Hom}_\Lambda(H^{0}(\mathbf{P}),H^{-1}(\mathbf{P})/R_n)=0\}
		=\min\{n\ge0:H^{-1}(\mathbf{P})/R_n\in\mathcal{F}\}.
	\end{equation}

Let $\Gamma$ be the path algebra of the oriented $E_6$ quiver in
Figure~\ref{fig:e6}, and set $T=\bigoplus_{i=1}^6T_i$ with the summands
marked in the Auslander--Reiten quiver in Figure~\ref{fig:are6}.
Write $R_i=e_i\Gamma$ and $S_i^\Gamma=R_i/\operatorname{rad} R_i$. Then
\[
T_1=S_6^\Gamma,\quad T_2=Y,\quad T_3=R_1,\quad
T_4=S_1^\Gamma,\quad T_5=R_6,\quad T_6=R_4,
\]
where $Y$ has space $k$ at every vertex and identity arrow maps.
Since $\Gamma$ is hereditary, $\operatorname{pd}_\Gamma T\le1$,
and a direct calculation gives $\operatorname{Ext}^1_\Gamma(T,T)=0$.
Together with the short exact sequence
\[0\to \Gamma \to T_3^3\oplus T_5^3\oplus T_6\to T_1\oplus T_2\oplus T_4\to 0,\]
this proves that the $\Gamma$-module $T$ is tilting.

