\label{prop:nilpotent-first-defect}
	For the pair $(\Lambda_{\phi},\mathbf{P}_{\phi})$, we have
	\begin{equation}\label{eq:nilpotent-negative-hom}
		\operatorname{Hom}_{\mathrm K^{\mathrm b}(\operatorname{proj} \Lambda_{\phi})}(\mathbf{P}_{\phi},\mathbf{P}_{\phi}[-1])
		\simeq(\ker \phi)^{2}.
	\end{equation}
	Moreover, its first HRS ideal is
	$I_1=\mathcal M_{\phi}(\ker \phi).$

\label{thm:nilpotent-operator-defect}
	The even HRS filtration associated with $\mathbf{P}_{\phi}$ is
	\begin{equation}\label{eq:nilpotent-defect-filtration}
		I_m=\mathcal M_{\phi}(K_m)
		\quad(m\ge0).
	\end{equation}
	Consequently,
	$h_{\Lambda_{\phi}}(\mathcal{T}(\mathbf{P}_{\phi}))=\nu(\phi).$

\label{cor:nilpotent-profile-dimensions}
	For every $m\ge0$,
	\begin{equation}\label{eq:nilpotent-profile-dimensions}
		\dim_k(I_{m+1}/I_m)=4c_m,
		\qquad
		\dim_k\operatorname{Hom}_{\mathrm K^{\mathrm b}(\operatorname{proj} \Lambda_m)}(\mathbf{P}_m,\mathbf{P}_m[-1])=2c_m.
	\end{equation}
	In particular, $\mathbf{P}_m$ first becomes tilting at $m=\nu(\phi)$.
